<?php
require_once __DIR__.'/../includes/auth.php';
requireActiveUser();requireTenantContext();requireModulePermission('support','view');
global $conn;$tenantId=(int)getCurrentTenantId();$userId=(int)getCurrentUserId();
$errors=[];$notice='';$ticketId=(int)($_GET['id']??$_POST['ticket_id']??0);
$statuses=['open','in_progress','waiting_customer','resolved','closed'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 requireCsrf();requireModulePermission('support','edit');
 $action=trim((string)($_POST['action']??''));$message=trim((string)($_POST['message']??''));$status=trim((string)($_POST['status']??''));$assignee=(int)($_POST['assigned_user_id']??0);
 $check=$conn->prepare("SELECT id,status FROM customer_support_tickets WHERE id=? AND tenant_id=? LIMIT 1");
 if($ticketId<=0||!$check)$errors[]='Select a valid support ticket.';
 else{$check->bind_param('ii',$ticketId,$tenantId);$check->execute();$ticket=$check->get_result()->fetch_assoc();$check->close();if(!$ticket)$errors[]='Support ticket not found for this organisation.';}
 if($action==='reply'&&($message===''||mb_strlen($message)>5000))$errors[]='Enter a reply of up to 5,000 characters.';
 if($action==='update'&&!in_array($status,$statuses,true))$errors[]='Select a valid ticket status.';
 if(!$errors&&$assignee>0){$q=$conn->prepare("SELECT id FROM users WHERE id=? AND tenant_id=? AND user_scope='tenant' AND LOWER(status)='active' LIMIT 1");if($q){$q->bind_param('ii',$assignee,$tenantId);$q->execute();$ok=(bool)$q->get_result()->fetch_assoc();$q->close();if(!$ok)$errors[]='Select an active staff user in this organisation.';}else $errors[]='Unable to verify staff assignment.';}
 if(!$errors&&$action==='reply'){
  $conn->begin_transaction();
  try{$q=$conn->prepare("INSERT INTO customer_support_messages (tenant_id,ticket_id,sender_type,sender_id,message) VALUES (?,?,'staff',?,?)");if(!$q)throw new RuntimeException('Unable to prepare support reply.');$q->bind_param('iiis',$tenantId,$ticketId,$userId,$message);if(!$q->execute())throw new RuntimeException('Unable to save support reply.');$q->close();$q=$conn->prepare("UPDATE customer_support_tickets SET last_message_at=NOW(),status=IF(status='waiting_customer','in_progress',status) WHERE id=? AND tenant_id=?");if(!$q)throw new RuntimeException('Unable to update ticket activity.');$q->bind_param('ii',$ticketId,$tenantId);if(!$q->execute())throw new RuntimeException('Unable to update ticket activity.');$q->close();$conn->commit();header('Location: tenant_tickets.php?id='.$ticketId.'&replied=1');exit;}catch(Throwable $e){$conn->rollback();$errors[]=$e->getMessage();}
 }elseif(!$errors&&$action==='update'){
  $resolvedAt=$status==='resolved'?date('Y-m-d H:i:s'):null;$closedAt=$status==='closed'?date('Y-m-d H:i:s'):null;$assigneeValue=$assignee>0?$assignee:null;
  $q=$conn->prepare("UPDATE customer_support_tickets SET status=?,assigned_user_id=?,resolved_at=?,closed_at=? WHERE id=? AND tenant_id=?");
  if(!$q)$errors[]='Unable to prepare support ticket update.';
  else{$q->bind_param('sissii',$status,$assigneeValue,$resolvedAt,$closedAt,$ticketId,$tenantId);if($q->execute())$notice='Ticket updated.';else $errors[]='Unable to update ticket.';$q->close();}
 }else if(!$errors)$errors[]='Invalid support action.';
}
if(isset($_GET['replied']))$notice='Reply sent.';
$tickets=[];$ticket=null;$messages=[];$staff=[];
$q=$conn->prepare("SELECT id,username FROM users WHERE tenant_id=? AND user_scope='tenant' AND LOWER(status)='active' ORDER BY username");
if($q){$q->bind_param('i',$tenantId);$q->execute();$r=$q->get_result();while($x=$r->fetch_assoc())$staff[]=$x;$q->close();}
$q=$conn->prepare("SELECT t.*,c.customer_number,TRIM(CONCAT_WS(' ',c.first_name,c.last_name)) customer_name FROM customer_support_tickets t INNER JOIN customers c ON c.id=t.customer_id AND c.tenant_id=t.tenant_id WHERE t.tenant_id=? ORDER BY FIELD(t.status,'open','in_progress','waiting_customer','resolved','closed'),t.priority DESC,t.updated_at DESC LIMIT 300");
if($q){$q->bind_param('i',$tenantId);$q->execute();$r=$q->get_result();while($x=$r->fetch_assoc())$tickets[]=$x;$q->close();}
if($ticketId>0){$q=$conn->prepare("SELECT t.*,c.customer_number,TRIM(CONCAT_WS(' ',c.first_name,c.last_name)) customer_name FROM customer_support_tickets t INNER JOIN customers c ON c.id=t.customer_id AND c.tenant_id=t.tenant_id WHERE t.id=? AND t.tenant_id=? LIMIT 1");if($q){$q->bind_param('ii',$ticketId,$tenantId);$q->execute();$ticket=$q->get_result()->fetch_assoc();$q->close();}if($ticket){$q=$conn->prepare("SELECT * FROM customer_support_messages WHERE ticket_id=? AND tenant_id=? ORDER BY id");if($q){$q->bind_param('ii',$ticketId,$tenantId);$q->execute();$r=$q->get_result();while($x=$r->fetch_assoc())$messages[]=$x;$q->close();}}}
$pageTitle='Customer Support Tickets';require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/../includes/sidebar.php';
?>
<div class="main-content tenant-support"><div class="support-hero"><div><span>CUSTOMER CARE</span><h1>Customer Support Tickets</h1><p>Review requests submitted through the customer portal and respond within your organisation.</p></div></div>
<?php foreach($errors as $e): ?><div class="support-alert error"><?=e($e)?></div><?php endforeach; ?><?php if($notice): ?><div class="support-alert success"><?=e($notice)?></div><?php endif; ?>
<div class="support-layout"><section class="support-panel"><h2><?= $ticket ? e($ticket['ticket_number'].' · '.$ticket['subject']) : 'Ticket Queue' ?></h2><?php if($ticket): ?><p><?=e(($ticket['customer_number']??'').' — '.($ticket['customer_name']??''))?> · <?=e(ucfirst($ticket['priority']))?></p><div class="support-thread"><?php foreach($messages as $m): ?><article class="<?=$m['sender_type']==='staff'?'staff-message':'customer-message'?>"><small><?=$m['sender_type']==='staff'?'Staff':'Customer'?> · <?=e($m['created_at'])?></small><p><?=nl2br(e($m['message']))?></p></article><?php endforeach; ?></div><form method="post" class="support-reply"><?=csrfField()?><input type="hidden" name="action" value="reply"><input type="hidden" name="ticket_id" value="<?=$ticketId?>"><textarea name="message" rows="3" maxlength="5000" required placeholder="Reply to customer..."></textarea><button class="btn btn-primary">Send Reply</button></form><form method="post" class="support-update"><?=csrfField()?><input type="hidden" name="action" value="update"><input type="hidden" name="ticket_id" value="<?=$ticketId?>"><label>Status<select name="status"><?php foreach($statuses as $status): ?><option value="<?=$status?>" <?=$ticket['status']===$status?'selected':''?>><?=ucwords(str_replace('_',' ',$status))?></option><?php endforeach; ?></select></label><label>Assigned Staff<select name="assigned_user_id"><option value="0">Unassigned</option><?php foreach($staff as $person): ?><option value="<?=(int)$person['id']?>" <?=(int)$ticket['assigned_user_id']===(int)$person['id']?'selected':''?>><?=e($person['full_name']??$person['username'])?></option><?php endforeach; ?></select></label><button class="btn btn-secondary">Update Ticket</button></form><?php else: ?><p>Select a ticket from the queue to view the conversation and manage its status.</p><?php endif; ?></section><aside class="support-panel"><h2>Ticket Queue</h2><?php foreach($tickets as $t): ?><a class="support-ticket" href="tenant_tickets.php?id=<?=(int)$t['id']?>"><strong><?=e($t['ticket_number'])?></strong><span><?=e($t['subject'])?></span><small><?=e($t['customer_number'].' · '.$t['customer_name'])?></small><small><?=e(ucwords(str_replace('_',' ',$t['status'])))?> · <?=e($t['priority'])?></small></a><?php endforeach; ?><?php if(!$tickets): ?><p>No customer support tickets yet.</p><?php endif; ?></aside></div></div>
